184	2347	d02e8ee8e68fe4850f73103acad91d7d453d9a1f41ad6111183b92437e60a614	25.08.07 EXAME EVA PEREIRA DA SILVA.pdf	SEDI II - SERVIÇO ESTADUAL DE DIAGNÓSTICO POR IMAGEM II - SECONCI - OSS	2025-07-15	1Ra1hmeYA2x2H5C3LYX53kwStuTd__zkr	recebido	1	gemini-2.5-flash	{"exams": [{"title": "COLANGIORRESSONÂNCIA", "sector": "ressonancia", "labName": "SEDI II - SERVIÇO ESTADUAL DE DIAGNÓSTICO POR IMAGEM II - SECONCI - OSS", "examType": "rmn", "findings": [{"field": "Coledoco distal", "level": null, "value": "Afilamento significativo do coledoco distal iniciando-se a cerca de 2,2 cm da papila, com dilatação à montante, medindo até 1,2 cm, sem falhas de enchimento. Espessamento e realce da parede do hepatocoledoco, não se podendo afastar colangite."}, {"field": "Vias biliares intra-hepáticas", "level": null, "value": "Dilatação das vias biliares intra-hepáticas, notadamente no lobo esquerdo."}, {"field": "Pâncreas (porção cefálica)", "level": null, "value": "Aumento e heterogeneidade da porção cefálica do pâncreas com restrição à difusão. Amputação do ducto pancreático principal na porção cefálica, com leve ectasia a montante medindo até 0,5 cm."}, {"field": "Relação com 2a porção duodenal", "level": null, "value": "Mantem intimo contato com a 2a porção duodneal."}, {"field": "Linfonodos adjacentes", "level": null, "value": "Linfonodos adjacentes proeminentes medindo até 1,0 x 0,7 cm."}, {"field": "Pâncreas (corpo e cauda)", "level": null, "value": "Corpo e cauda pancreatico com morfologia e sinal habituais."}, {"field": "Vesícula biliar", "level": null, "value": "Vesícula biliar com boa distensão, de paredes finas e regulares, com conteudo heterogêneo, que deve corresponder a microcálculos e/ou lama biliar."}, {"field": "Fígado", "level": null, "value": "Fígado de dimensões normais, contornos regulares."}, {"field": "Formações císticas hepáticas", "level": null, "value": "Formações cisticas esparsas no parênquima hepático, as maiores assim localizadas:"}, {"field": "segmento II/III", "level": null, "value": "medindo 7,9 x 6,0 cm, com septações de permeio."}, {"field": "segmento IVa", "level": null, "value": "medindo 2,5 x 2,1 cm, com finas septações."}, {"field": "segmento VII", "level": null, "value": "medindo 0,7 cm."}, {"field": "Veias hepáticas e ramos portais", "level": null, "value": "Veias hepáticas e ramos portais preservados."}, {"field": "Baço", "level": null, "value": "Baço de dimensões normais, contornos regulares e intensidade de sinal preservada."}, {"field": "Adrenais", "level": null, "value": "Adrenais de morfologia, dimensões e sinal usuais."}], "conclusion": "Afilamento significativo do colédoco distal com dilatação à montante e das vias biliares intra-hepáticas. Aumento e heterogeneidade da porção cefálica do pâncreas com restrição à difusão e amputação do ducto pancreático principal. Linfonodos adjacentes proeminentes. Vesícula biliar com conteúdo heterogêneo (microcálculos/lama biliar). Formações císticas esparsas no parênquima hepático.", "comparativo": null, "collectionDate": "15/07/2025"}], "patient": {"cpf": null, "name": null, "birthDate": null}, "confidence": 1}	2026-07-10 21:23:32.586471+00	\N	\N	\N	\N	\N	\N	\N	\N	\N	drive-import	Eva Pereira Da Silva / EXAMES	imagem	5	0	\N	[]
