COPY public.narrativas_agente (id, agente_id, titulo, contexto, roteiro, criado_em) FROM stdin;
1	1	Confirmação de Agendamento Pós-Protocolo	Cliente que finalizou protocolo pergunta sobre reagendamento	[{"papel": "cliente", "texto": "Oi, terminei o protocolo. Quero continuar, como faço?"}, {"papel": "agente", "texto": "Que ótimo saber que você quer continuar! Vou verificar a disponibilidade do Dr. Caio para uma consulta de renovação. Qual período você prefere — manhã ou tarde?"}, {"papel": "cliente", "texto": "Tarde, preferencialmente."}, {"papel": "agente", "texto": "Perfeito! Temos vaga na terça-feira às 15h. Confirmo?"}, {"papel": "cliente", "texto": "Sim, pode confirmar."}, {"papel": "agente", "texto": "Consulta agendada! Você receberá a confirmação por e-mail agora. Até lá!"}]	2026-07-19 02:44:35.072384+00
2	3	Avaliação de Sintoma Durante Aplicação	Cliente relata tontura durante sessão de endovenoso	[{"papel": "cliente", "texto": "Estou me sentindo um pouco tonta durante a aplicação."}, {"papel": "agente", "texto": "Vamos pausar a aplicação agora. TONTURA reportada. Lia, pause o procedimento. Clara aqui — vou avaliar. Você está sentada ou deitada?"}, {"papel": "cliente", "texto": "Deitada."}, {"papel": "agente", "texto": "Ótimo. Vou verificar sua pressão e saturação. Respire fundo comigo. Isso é normal em alguns casos mas vamos cuidar com atenção."}, {"papel": "cliente", "texto": "Obrigada, já melhorou um pouco."}, {"papel": "agente", "texto": "Fico feliz. Vamos aguardar 5 minutos antes de retomar, com monitoramento contínuo. Acionei o Dr. Caio por precaução — ele acompanhará à distância."}]	2026-07-19 02:44:35.082486+00
3	7	Negociação de Parcela em Atraso	Cliente com parcela vencida há 10 dias entra em contato	[{"papel": "cliente", "texto": "Vi que tenho uma parcela atrasada. Posso negociar?"}, {"papel": "agente", "texto": "Claro! Parcela de R$ 450,00 vencida em 10/07. Temos duas opções: regularizar hoje com desconto de 5% na multa, ou parcelar em mais 2x sem juros adicionais. Qual prefere?"}, {"papel": "cliente", "texto": "Posso pagar hoje, mas quero o desconto."}, {"papel": "agente", "texto": "Aprovado! Valor com desconto: R$ 427,50. Envio o PIX agora. Após o pagamento me mande o comprovante e regularizo no sistema em até 1 hora."}, {"papel": "cliente", "texto": "Pago agora."}, {"papel": "agente", "texto": "Perfeito! Pagamento registrado e protocolo normalizado. Obrigada pela agilidade!"}]	2026-07-19 02:44:35.09289+00
4	17	Reclamação sobre Atendimento	Cliente insatisfeito com demora no retorno	[{"papel": "cliente", "texto": "Faz 3 dias que mandei mensagem e ninguém respondeu. Estou insatisfeito."}, {"papel": "agente", "texto": "Sinto muito pelo transtorno. Isso não deveria ter acontecido. Pode me dar mais detalhes sobre quando e como entrou em contato?"}, {"papel": "cliente", "texto": "Mandei WhatsApp na terça à tarde."}, {"papel": "agente", "texto": "Entendi. Vou investigar o que ocorreu e garantir que isso não se repita. Abri um protocolo com prioridade. Você receberá um retorno nosso até amanhã ao meio-dia. Posso registrar algo mais?"}, {"papel": "cliente", "texto": "Não. Só quero uma resposta."}, {"papel": "agente", "texto": "Garantido. Protocolo aberto. Muito obrigada pela confiança em nos comunicar. Faremos melhor."}]	2026-07-19 02:44:35.108768+00
